WITH RankedData AS ( SELECT m.INDX_SNAME, m.SECCODE, m.LCLOSE, m.TCLOSE, ROW_NUMBER() OVER (ORDER BY m.TRADEDATE ASC) AS rn_asc, ROW_NUMBER() OVER (ORDER BY m.TRADEDATE DESC) AS rn_desc FROM INDX_MKT m INNER JOIN GET_INDX_GEN_INFO g ON m.INNER_CODE = g.INNER_CODE WHERE m.SECCODE = '000016' AND m.TRADEDATE >= '2025-01-01' AND m.TRADEDATE <= '2025-12-31' AND m.ISVALID = 1 AND g.ISVALID = 1 AND g.USE_STATUS = '使用' AND m.TCLOSE IS NOT NULL AND m.LCLOSE IS NOT NULL ) SELECT MAX(INDX_SNAME) AS `指数名称`, MAX(SECCODE) AS `指数代码`, ROUND(MAX(CASE WHEN rn_asc = 1 THEN LCLOSE END), 2) AS `年初昨收`, ROUND(MAX(CASE WHEN rn_desc = 1 THEN TCLOSE END), 2) AS `年末收盘`, ROUND((MAX(CASE WHEN rn_desc = 1 THEN TCLOSE END) - MAX(CASE WHEN rn_asc = 1 THEN LCLOSE END)) / NULLIF(MAX(CASE WHEN rn_asc = 1 THEN LCLOSE END), 0) * 100, 2) AS `2025年全年涨跌幅(%)` FROM RankedData;
